import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-11-05","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-11-05","date":"2025-11-05T00:00:00.000Z","updated":"2025-12-04T00:00:00.000Z","tags":["Ceph","RGW","Distributed Storage","OpenStack","BI Log","Valgrind"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-05.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-05.md","lastUpdated":1780460162000}'),o={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-05.md"};function n(r,l,s,g,h,d){return i(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="ceph-rgw-重构会议纪要" tabindex="-1">Ceph RGW 重构会议纪要 <a class="header-anchor" href="#ceph-rgw-重构会议纪要" aria-label="Permalink to &quot;Ceph RGW 重构会议纪要&quot;">​</a></h3><p><strong>日期</strong>：2025年11月5日<br><strong>参会人员</strong>：Phillip, Shelpa 等核心开发成员</p><h3 id="_1-议题讨论与关键细节" tabindex="-1">1. 议题讨论与关键细节 <a class="header-anchor" href="#_1-议题讨论与关键细节" aria-label="Permalink to &quot;1. 议题讨论与关键细节&quot;">​</a></h3><h4 id="_1-rgw-valgrind-问题修复" tabindex="-1">(1) RGW Valgrind 问题修复 <a class="header-anchor" href="#_1-rgw-valgrind-问题修复" aria-label="Permalink to &quot;(1) RGW Valgrind 问题修复&quot;">​</a></h4><ul><li><strong>问题描述</strong>：近期 RGW 测试中出现了大量 Valgrind 报错，原因是构建流程中遗漏了 <code>boost valgrind</code> 定义。</li><li><strong>解决方案</strong>：已经修复了这一问题，并将在 Slack 上同步测试结果，后续集中处理剩余问题。</li><li><strong>行动计划</strong>： <ul><li>合并修复补丁后建立干净的测试基线。</li><li>团队协作修复剩余的 Valgrind 报错。</li></ul></li></ul><h4 id="_2-keystone-审计功能开发-phillip" tabindex="-1">(2) Keystone 审计功能开发（Phillip） <a class="header-anchor" href="#_2-keystone-审计功能开发-phillip" aria-label="Permalink to &quot;(2) Keystone 审计功能开发（Phillip）&quot;">​</a></h4><ul><li><strong>需求背景</strong>：客户需要审计 Keystone 对 RGW 的访问日志，目前缺乏数据收集能力。</li><li><strong>实现方案</strong>： <ul><li>将 Keystone 的 scope 数据转发到 Ops Log。</li><li>提供三个开关选项，包括合规性相关的用户身份信息过滤。</li></ul></li><li><strong>讨论要点</strong>： <ul><li>代码审查由常规 Reviewer 负责，但需要 OpenStack 专家（如 Keystone 相关开发者）确认设计合理性。</li><li>Phillip 已提交详细设计文档，团队认为当前实现逻辑清晰。</li></ul></li><li><strong>后续行动</strong>： <ul><li>在 PR 中标记相关 OpenStack 专家进行评审。</li><li>Phillip 根据反馈调整代码。</li></ul></li></ul><h4 id="_3-bi-log-重构与-fifo-后端设计-shelpa" tabindex="-1">(3) BI Log 重构与 FIFO 后端设计（Shelpa） <a class="header-anchor" href="#_3-bi-log-重构与-fifo-后端设计-shelpa" aria-label="Permalink to &quot;(3) BI Log 重构与 FIFO 后端设计（Shelpa）&quot;">​</a></h4><ul><li><strong>目标</strong>：分离 BI Log（Bucket Index Log）与 Bucket Index 数据以提升扩展性。</li><li><strong>关键变更</strong>： <ul><li><strong>CLS 层</strong>：分离 BI Log 和 Bucket Index 的操作逻辑。</li><li><strong>后端选择</strong>：基于 <code>bucket index log layout type</code> 动态路由，默认目标为 FIFO 后端。</li><li><strong>FIFO 设计</strong>： <ul><li>单 FIFO 对象/桶（未分片，避免与 Bucket Index 分片耦合）。</li><li>支持同步/异步接口（当前仅测试同步）。</li><li>异步批处理功能预留（暂不启用）。</li></ul></li></ul></li><li><strong>开放问题</strong>： <ul><li><strong>分片必要性</strong>：Bucket Sync 依赖多分片并行处理，需评估是否引入默认分片。</li><li><strong>数据迁移</strong>：从 OMAP 迁移到 FIFO 时需处理旧日志读取，计划采用 generation-based 方案。</li></ul></li><li><strong>后续计划</strong>： <ul><li>完善设计文档与草案 PR。</li><li>优先验证同步逻辑，后续逐步启用异步和批处理优化。</li></ul></li></ul><h3 id="_2-决议事项" tabindex="-1">2. 决议事项 <a class="header-anchor" href="#_2-决议事项" aria-label="Permalink to &quot;2. 决议事项&quot;">​</a></h3><ol><li>合并 Valgrind 定义修复后推进问题闭环。</li><li>代码通过常规评审后，由 OpenStack 专家确认 Keystone 集成部分。</li><li>初步采用单 FIFO 设计，后续讨论分片策略。</li><li>同步接口优先，稳定后逐步启用异步优化。</li></ol><h3 id="_3-后续行动计划" tabindex="-1">3. 后续行动计划 <a class="header-anchor" href="#_3-后续行动计划" aria-label="Permalink to &quot;3. 后续行动计划&quot;">​</a></h3><p>| 任务 | 负责人 | 时间节点 | ||--|-| | RGW Valgrind 修复合并 | 发起人 | 近期 | | Keystone 审计 PR 评审 | Phillip + OpenStack 专家 | 本周内 | | BI Log 分片方案讨论 | Shelpa + Adam | 下阶段会议 | | FIFO 异步接口测试 | Shelpa | 功能稳定后 |</p><p><strong>备注</strong>：</p><ul><li>关键词保留：RGW, BI Log, FIFO, CLS, OMAP, Keystone, Valgrind, async/sync.</li><li>下次会议将重点跟进 BI Log 分片设计与迁移逻辑。</li></ul><p><strong>会议结束</strong>：全体成员确认无其他议题后散会。</p>',16)])])}const u=e(o,[["render",n]]);export{c as __pageData,u as default};
